/* Furora front end. Data is kept in localStorage until you connect a real backend. */
const K="furora:v3",PAGE=document.body.dataset.page,$=s=>document.querySelector(s);
const DB=()=>{try{return JSON.parse(localStorage.getItem(K))||{users:{},session:null,threads:[]}}catch(e){return{users:{},session:null,threads:[]}}};
const put=d=>localStorage.setItem(K,JSON.stringify(d));
const me=()=>{const d=DB();return d.users[d.session]||null};
const patch=f=>{const d=DB();if(d.users[d.session]){f(d.users[d.session],d);put(d)}};
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const cr=n=>String(Math.round(n*100)/100);
const uid=()=>Math.random().toString(36).slice(2,9);
async function sha(p,s){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s+p));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}
function toast(m){const t=$("#toast");t.textContent=m;t.style.display="block";clearTimeout(toast.t);toast.t=setTimeout(()=>t.style.display="none",3000)}
