/* ================================================= */
async function wp(t){const c=sessionStorage.getItem("wp:"+t);if(c)return c;try{const j=await(await fetch("https://en.wikipedia.org/api/rest_v1/page/summary/"+encodeURIComponent(t))).json();let s=j.thumbnail&&j.thumbnail.source;if(s){s=s.replace(/\/\d+px-/,"/800px-");sessionStorage.setItem("wp:"+t,s);return s}}catch(e){}return""}
function cands(f){const m=f.match(/^(.*\/)?([^\/]+)\.\w+$/),dir=(m&&m[1])||"",base=m?m[2]:f,L=[];[dir,"img/",""].forEach(d=>["jpg","jpeg","png","webp"].forEach(e=>{const p=d+base+"."+e;if(!L.includes(p))L.push(p)}));return L}
function tryImg(L,ok,no){if(!L.length)return no();const im=new Image();im.onload=()=>ok(L[0]);im.onerror=()=>tryImg(L.slice(1),ok,no);im.src=encodeURI(L[0])}
function hydrate(){document.querySelectorAll("[data-img],[data-wp]").forEach(el=>{const f=el.dataset.img,w=el.dataset.wp,use=u=>{el.style.backgroundImage=`url("${encodeURI(u)}")`;el.classList.add("loaded")},fb=()=>{if(f)el.setAttribute("data-miss",f)};f?tryImg(cands(f),use,fb):fb()})}
