function guard(){const u=me(),pub=["about","sustainability","refunds","cookies","contact"].includes(PAGE),go=p=>{location.replace(p);return false};
 if(!u)return PAGE=="index"||pub||go("index.html");if(pub)return true;
 if(!u.terms)return PAGE=="terms"||go("terms.html");
 if(!u.pet.breed)return PAGE=="breed"||go("breed.html");if(!u.pet.name)return PAGE=="setup"||go("setup.html");
 return!["index","terms","breed","setup"].includes(PAGE)||go("home.html")}
const gate=()=>`<div class="card sun"><h3>Please sign in</h3><p>This area uses your Furora account.</p><a class="btn" href="index.html">Sign in</a></div>`;
