const descHtml=d=>`${(d.i||"").split("\n").filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join("")}${d.f.length?`<div class="fl">✦ Highlights</div><ol class="feat">${d.f.map(t=>`<li>${esc(t)}</li>`).join("")}</ol>`:""}${d.ex.map(t=>`<div class="xtra">${esc(t)}</div>`).join("")}`;
P.shop=()=>{const o=me().orders||[];return `<span class="kicker">Pet shopping</span><h1>Our pet shops.</h1><p class="mut">Choose a shop to browse its products and pay with your credits. Your balance: <b>${cr(me().credits||0)}</b> credits.</p><div class="grid cards">${SHOPS.map(x=>`<a class="tile" href="store.html?s=${x.id}" style="text-decoration:none;color:inherit">${ph(x,"aspect-ratio:4/3")}<div class="in"><h3>${esc(x.n)}</h3><span class="mut">${esc(x.d)}</span></div></a>`).join("")}</div><div class="card sky" style="margin-top:36px"><h3>Run a pet shop in North Macedonia?</h3><p>Apply as a provider to open a shop here once verified.</p><a class="btn sm line" href="providers.html">Apply as a provider</a></div><p style="margin-top:36px"><a href="pet.html#orders">Track my orders</a></p>`};
let SH=null;
P.store=()=>{SH=SHOPS.find(x=>x.id==new URLSearchParams(location.search).get("s"));if(!SH)return `<h1>Shop not found</h1><a href="shop.html">Back to all shops</a>`;
 return `<p><a href="shop.html">← All shops</a></p><span class="kicker">Pet shop</span><h1>${esc(SH.n)}</h1><p class="mut">${esc(SH.d)} Your balance: <b>${cr(me().credits||0)}</b> credits. <a href="credits.html">Add credits</a></p><div class="grid cards">${SH.items.map((x,i)=>`<div class="cw"><button class="tile" onclick="prodOpen(${i})">${ph({wp:x[3],file:x[4],fit:true},"aspect-ratio:4/3")}<div class="in"><h3>${esc(x[0])}</h3><span class="mut">€${(x[5]/MKD_PER_EUR).toFixed(2)} · ${cr(x[1])} credits</span></div></button>${acts(snapS(SH,x))}</div>`).join("")}</div>
<dialog id="pd"><div id="pph"></div><div class="db"><h2 id="pn2"></h2><p class="mut" id="pc2"></p><div id="pde"></div><div class="row" style="gap:10px;margin-top:20px"><button class="btn" id="po2">Add to cart</button><button class="btn line" onclick="$('#pd').close()">Close</button></div></div></dialog>`};
function prodOpen(i){const x=SH.items[i];$("#pph").innerHTML=ph({wp:x[3],file:x[4],fit:true},"aspect-ratio:16/10");$("#pn2").textContent=x[0];$("#pc2").textContent=`${x[5]} MKD · €${(x[5]/MKD_PER_EUR).toFixed(2)} · ${cr(x[1])} credits`;$("#pde").innerHTML=descHtml(x[2]);
 $("#po2").onclick=()=>{SNAP.push(snapS(SH,x));addCart(SNAP.length-1);$("#pd").close()};$("#pd").showModal();hydrate()}
let tstep=1;
P.terms=()=>tstep==1?`<div style="max-width:720px;margin:auto"><span class="kicker">Before you begin</span><h1>Terms and Conditions</h1><p class="mut">Please read and accept to continue.</p><div class="terms" tabindex="0"><h3>1. Using Furora</h3><p>Furora connects pet owners with veterinarians, groomers, trainers, shelters and other pet businesses. You must be 18 or older to create an account.</p><h3>2. Your account</h3><p>You are responsible for keeping your password secure and for the accuracy of the information you provide.</p><h3>3. Credits</h3><p>Credits are prepaid service value. Purchased credits are non-refundable, non-transferable, cannot be withdrawn as cash and are held when you book. Our cancellation and refund policy explains how credits are returned or paid to providers.</p><h3>4. Bookings and providers</h3><p>Services are delivered by independent providers. Furora facilitates bookings and is not responsible for the professional services provided.</p><h3>5. Veterinary information</h3><p>Content on Furora does not replace a veterinarian’s diagnosis, treatment or emergency care.</p><h3>6. Adoption</h3><p>Our compatibility questionnaire is guidance only. Shelters make all adoption decisions.</p><h3>7. Swap and community</h3><p>Items you list are inspected before they are shared. Medicines, recalled or unsafe items, expired food and animals are not allowed. Be respectful in discussions.</p><h3>8. Privacy</h3><p>We collect only the information needed to run the service, and never sell personal data. You can download or delete your data from Account settings.</p><h3>9. Changes</h3><p>We may update these terms and will tell you about important changes.</p></div><form id="tf" style="margin-top:24px"><label style="font-weight:400;font-size:1rem;letter-spacing:0"><input type="checkbox" id="tc" required> I have read and accept the Terms and Conditions and Privacy Policy.</label><button class="btn" style="margin-top:20px">Accept and continue</button></form><dialog id="cd"><div class="db"><span class="kicker">Please read carefully</span><h2>Credits</h2><p>Credits are a limited, non-transferable right to access specified services or features within the website. They are not legal tender, currency, a deposit, stored-value instrument, financial product, or gift card or gift certificate, and have no cash value. Credits may only be used within the website for the services for which they were issued. Pricing is set at the time of purchase as displayed in the website; we may change Credit pricing, package sizes, or available services at any time, effective prospectively. Previously purchased Credits retain the value they had at the time of purchase.</p><div class="row" style="gap:10px"><button class="btn" id="ca">Accept and Continue</button><button class="btn line" id="cr">Reject and Leave</button></div></div></dialog></div>`:`<div style="max-width:620px;margin:auto"><span class="kicker">One more thing</span><h1>Would you like to hear from us?</h1><p class="mut">We can email you offers, news and pet-care tips. You can change this any time in Account settings.</p><form class="card" id="pf"><label style="font-weight:400;font-size:1rem;letter-spacing:0"><input type="radio" name="pr" value="1" checked> Yes, send me promotional emails</label><label style="font-weight:400;font-size:1rem;letter-spacing:0"><input type="radio" name="pr" value="0"> No thanks, only important account emails</label><button class="btn" style="margin-top:22px">Continue</button></form></div>`;
P.terms.after=()=>{if(tstep==1){$("#tf").onsubmit=e=>{e.preventDefault();$("#cd").showModal()};$("#ca").onclick=()=>{patch(u=>{u.terms={at:Date.now()};u.creditsAck={at:Date.now()}});tstep=2;draw()};$("#cr").onclick=()=>{$("#cd").close();$("#tc").checked=false;window.scrollTo(0,0)}}else $("#pf").onsubmit=e=>{e.preventDefault();patch(u=>u.promo=document.querySelector('input[name=pr]:checked').value=="1");location.href="breed.html"}};
P.refunds=()=>`<div style="max-width:720px"><span class="kicker">Policy</span><h1>Cancellations and refunds</h1><div class="note"><b>Purchased credits are non-refundable.</b></div><h3>When you book</h3><p>The credits for a booking are held from your balance. They are not paid to the provider yet.</p><h3>If you cancel</h3><p>Cancel a booking from Services and the held credits return to your wallet straight away.</p><h3>If a provider cancels</h3><p>The held credits are returned to your wallet in full.</p><h3>After the service</h3><p>When you confirm the service was completed, the credits are paid to the provider, less Furora’s commission. If something went wrong, contact us before you confirm.</p><h3>No refunds on purchased credits</h3><p>Purchased credits are non-refundable and cannot be withdrawn as cash, except where the law requires otherwise. Credits returned after a cancellation go back to your Furora wallet, not to your card.</p></div>`;
P.veterinary=()=>`<span class="kicker">Veterinary</span><h1>Care you can trust.</h1><div class="note"><b>Emergency?</b> Go to the nearest clinic or call a vet now. Furora is not an emergency service.</div><div class="grid"><div class="card sky"><h3>Book a visit</h3><p>Check-ups and vaccinations are booked with licensed veterinarians using credits.</p><a class="btn sm" href="services.html" onclick="">Choose a vet</a></div><div class="card"><h3>Keep records</h3><p>Store vaccinations, medical history and allergies in My pet and bring them to every visit.</p><a href="pet.html">Open My pet</a></div><div class="card sun"><h3>Remote consultations</h3><p>Not available yet. They will start only after legal and professional requirements are confirmed.</p></div></div><h2 style="margin-top:56px">Owner basics</h2><p>Dogs in North Macedonia must be registered and identified. See the Food and Veterinary Agency’s guidance on pet welfare, and your municipality’s rules.</p>`;
P.providers=()=>{const d=DB(),ap=d.providers||[];return `<span class="kicker">Providers</span><h1>Verified local businesses</h1><p class="mut">Local pet businesses on Furora. Only verified providers can be booked.</p><div class="grid">${PROV.map((p,i)=>`<button class="card pcard" onclick="provOpen(${i})"><span class="tag y">${LIST[p[1]]} Listing</span><h3 style="margin-top:12px">${esc(p[0])}</h3><span class="mut">Tap to learn more</span></button>`).join("")}<dialog id="pv"><div class="db"><span class="tag y" id="pvt"></span><h2 id="pvn" style="margin-top:10px"></h2><p id="pvd"></p><div id="pvc" style="margin-bottom:18px"></div><div class="row" style="gap:10px" id="pvb"></div></div></dialog></div><h2 style="margin-top:56px">Apply as a provider</h2><form class="card" style="max-width:600px" onsubmit="apply(event)"><label>Business name</label><input id="pn" required><div class="row"><div><label>Category</label><select id="pc">${CATS.slice(1).map(c=>`<option>${c[1]}</option>`).join("")}</select></div><div><label>City</label><input id="py" required></div></div><label>Email</label><input id="pe" type="email" required><label>Licence or registration details</label><textarea id="pl" rows="2" required></textarea><button class="btn" style="margin-top:20px">Submit application</button></form>${ap.length?`<p class="mut" style="margin-top:14px">${ap.length} application(s) pending verification.</p>`:""}`};
function provOpen(i){const p=PROV[i];$("#pvt").textContent=LIST[p[1]]+" Listing";$("#pvn").textContent=p[0];$("#pvd").textContent=p[3];$("#pvc").innerHTML=p[4].map(x=>`<span class="pill">${esc(x)}</span>`).join("");
 $("#pvb").innerHTML=(p[5]?`<a class="btn" href="${esc(p[5])}" target="_blank" rel="noopener noreferrer">Take me to their page</a>`:`<button class="btn" disabled title="Link coming soon">Take me to their page</button>`)+`<button class="btn line" onclick="$('#pv').close()">Cancel</button>`;$("#pv").showModal()}
function apply(e){e.preventDefault();patch((u,d)=>(d.providers=d.providers||[]).push({n:$("#pn").value,c:$("#pc").value,y:$("#py").value,e:$("#pe").value,l:$("#pl").value,st:"Pending"}));toast("Application received.");draw()}
const PT=[["basic","Basic information"],["pass","Passport"],["vacc","Vaccinations"],["med","Medical history"],["all","Allergies"],["about","About"],["wish","Wishlist"],["orders","My orders"]];let tab="basic",tabInit=false;
P.pet=()=>{if(!tabInit){tabInit=true;if(location.hash=="#orders")tab="orders";if(location.hash=="#wishlist")tab="wish"}const p=me().pet,due=(p.vacc||[]).filter(v=>v.next).sort((a,b)=>a.next>b.next?1:-1)[0];return `<div class="row" style="align-items:center;gap:26px;margin:36px 0 10px"><div style="flex:0 0 120px;min-width:0"><div class="photo has avatar" ${p.photo?`style="background-image:url('${p.photo}')"`:`data-img="img/basic-profile.jpg"`}>${p.photo?"":SIL}</div></div><div><span class="kicker">Pet profile</span><h1 style="margin:0">${esc(p.name)}</h1><p class="mut" style="margin:0">${esc(p.breed)}</p></div></div><div class="grid" style="margin:30px 0"><div class="card sky"><h3>Next vaccination</h3><p style="margin:0">${due?esc(due.n)+" on "+due.next:"None recorded"}</p></div><div class="card"><h3>Medical records</h3><p style="margin:0">${(p.med||[]).length} recorded</p></div><div class="card sun"><h3>Allergies</h3><p style="margin:0">${(p.all||[]).map(a=>esc(a.n)).join(", ")||"None recorded"}</p></div></div><div class="tabs">${PT.map(t=>`<button aria-pressed="${t[0]==tab}" onclick="tab='${t[0]}';draw()">${t[1]}</button>`).join("")}</div>${ptab(p)}`};
function lst(k,cols){const p=me().pet;return `<div class="scroll"><table><tr>${cols.map(c=>`<th>${c[1]}</th>`).join("")}<th></th></tr>${(p[k]||[]).map((r,i)=>`<tr>${cols.map(c=>`<td>${esc(r[c[0]])}</td>`).join("")}<td><button class="btn sm line" onclick="patch(u=>u.pet['${k}'].splice(${i},1));draw()">Remove</button></td></tr>`).join("")||`<tr><td colspan=9>Nothing recorded yet.</td></tr>`}</table></div><form class="card" style="margin-top:20px" onsubmit="addRow(event,'${k}')"><div class="row">${cols.map(c=>`<div><label>${c[1]}</label><input name="${c[0]}" ${c[2]||""}></div>`).join("")}</div><button class="btn sm" style="margin-top:18px">Add</button></form>`}
function ptab(p){if(tab=="orders")return ordersSec();if(tab=="wish")return wishSec();if(tab=="basic")return `<form class="card" onsubmit="sv(event,null)"><div class="row"><div><label>Name</label><input name="name" value="${esc(p.name)}"></div><div><label>Breed</label><select name="breed">${BREEDS.map(b=>`<option ${b[0]==p.breed?"selected":""}>${b[0]}</option>`).join("")}</select></div></div><div class="row"><div><label>Birthday</label><input type="date" name="bday" value="${esc(p.bday)}"></div><div><label>Sex</label><select name="sex">${["","Female","Male"].map(x=>`<option ${p.sex==x?"selected":""}>${x}</option>`).join("")}</select></div><div><label>Microchip</label><input name="chip" value="${esc(p.chip)}"></div></div><label>Photo (optional)</label><input type="file" accept="image/*" onchange="photo(this)"><button class="btn" style="margin-top:20px">Save</button></form>`;
 if(tab=="pass"){const b=p.pass||{};return `<form class="card" onsubmit="sv(event,'pass')"><div class="row"><div><label>Passport number</label><input name="no" value="${esc(b.no)}"></div><div><label>Issued by</label><input name="by" value="${esc(b.by)}"></div><div><label>Issue date</label><input type="date" name="on" value="${esc(b.on)}"></div></div><label>Notes</label><textarea name="n" rows="3">${esc(b.n)}</textarea><button class="btn" style="margin-top:20px">Save</button></form>`}
 if(tab=="vacc")return lst("vacc",[["n","Vaccine","required"],["d","Given","type=date"],["next","Next due","type=date"],["vet","Veterinarian"]]);
 if(tab=="med")return lst("med",[["d","Date","type=date"],["n","Condition or procedure","required"],["tx","Treatment"],["note","Notes"]]);
 if(tab=="all")return lst("all",[["n","Allergen","required"],["k","Type"],["r","Reaction"]]);
 return `<form class="card" onsubmit="sv(event,'about')"><label>Personality, habits and routines</label><textarea name="about" rows="8">${esc(p.about)}</textarea><button class="btn" style="margin-top:20px">Save</button></form>`}
function addRow(e,k){e.preventDefault();const o={};new FormData(e.target).forEach((v,n)=>o[n]=v);patch(u=>(u.pet[k]=u.pet[k]||[]).push(o));draw()}
function sv(e,k){e.preventDefault();const o={};new FormData(e.target).forEach((v,n)=>{if(typeof v=="string")o[n]=v});patch(u=>{if(k=="about")u.pet.about=o.about;else if(k)u.pet[k]=Object.assign(u.pet[k]||{},o);else Object.assign(u.pet,o)});toast("Saved.");nav();draw()}
function photo(i){const f=i.files[0];if(!f)return;const im=new Image();im.onload=()=>{const c=document.createElement("canvas");c.width=c.height=320;const m=Math.min(im.width,im.height);c.getContext("2d").drawImage(im,(im.width-m)/2,(im.height-m)/2,m,m,0,0,320,320);patch(u=>u.pet.photo=c.toDataURL("image/jpeg",.8));toast("Photo saved.");draw()};im.src=URL.createObjectURL(f)}
P.account=()=>{const u=me(),d=DB();return `<span class="kicker">Account</span><h1>Settings</h1><div class="grid g2"><form class="card" onsubmit="saveAcc(event)"><h3>Personal information</h3><label>Name</label><input id="an" value="${esc(u.name)}"><label>Email</label><input value="${esc(d.session)}" disabled><label style="font-weight:400"><input type="checkbox" id="av" ${u.nv!==false?"checked":""}> Vaccination reminders</label><label style="font-weight:400"><input type="checkbox" id="ab" ${u.nb!==false?"checked":""}> Booking updates</label><label style="font-weight:400"><input type="checkbox" id="ap" ${u.promo?"checked":""}> Promotional emails</label><button class="btn" style="margin-top:20px">Save changes</button></form><form class="card" onsubmit="chpw(event)"><h3>Change password</h3><label>Current password</label><input id="po" type="password" required autocomplete="current-password"><label>New password (8+ characters)</label><input id="pw" type="password" minlength="8" required autocomplete="new-password"><button class="btn" style="margin-top:20px">Change password</button></form><div class="card sky"><h3>Privacy</h3><p>Your data stays in this browser. Furora never sells personal data.</p><div style="display:flex;flex-direction:column;align-items:flex-start;gap:22px;margin-top:8px"><button class="btn sm line" onclick="exp()">Download my data</button><button class="btn sm warn" onclick="delAcc()">Delete account</button></div></div></div>`};
function saveAcc(e){e.preventDefault();patch(u=>{u.name=$("#an").value;u.nv=$("#av").checked;u.nb=$("#ab").checked;u.promo=$("#ap").checked});toast("Saved.")}
async function chpw(e){e.preventDefault();const u=me();if(u.h!==await sha($("#po").value,u.salt)){toast("Current password is incorrect.");return}const s=uid(),h=await sha($("#pw").value,s);patch(x=>{x.salt=s;x.h=h});e.target.reset();toast("Password changed.")}
function exp(){const u={...me()};delete u.h;delete u.salt;const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(u,null,2)],{type:"application/json"}));a.download="furora-my-data.json";a.click()}
function delAcc(){if(confirm("Delete your account and all its data? This cannot be undone.")){const d=DB();delete d.users[d.session];d.session=null;put(d);location.href="index.html"}}
const SD=[["3","Good Health and Well-Being","#4C9F38","#fff","Support access to responsible veterinary care and owner education; do not present the platform as a substitute for professional diagnosis or emergency treatment."],["8","Decent Work and Economic Growth","#A21942","#fff","Create paid digital, operations and community roles and provide local pet businesses with an additional customer-acquisition and booking channel."],["9","Industry, Innovation and Infrastructure","#FD6925","#1a1a1a","Develop a secure digital marketplace, booking workflow, provider tools and auditable credit ledger."],["11","Sustainable Cities and Communities","#FD9D24","#1a1a1a","Strengthen local animal-welfare partnerships and support responsible urban pet ownership."],["12","Responsible Consumption and Production","#BF8B2E","#1a1a1a","Enable reuse and swapping of safe second-hand pet accessories, reduce unnecessary purchases, and encourage recyclable/reusable packaging."],["13","Climate Action","#3F7E44","#fff","Use digital-first operations, efficient hosting and lower-emission delivery options; measure rather than overstate carbon savings."],["15","Life on Land","#56C02B","#1a1a1a","Support responsible adoption, rescue organisations and animal welfare; this is a contribution to the goal’s wider biodiversity and terrestrial-life agenda, not a claim that domestic pets are wildlife."],["17","Partnerships for the Goals","#19486A","#fff","Build measurable partnerships with shelters, veterinary professionals, local businesses, municipalities and eligible EU/donor programmes."]];
P.sustainability=()=>`<span class="kicker">Our impact</span><h1>Care that reaches beyond the clinic.</h1><p class="mut">We donate 3% of annual net profit after tax to vetted animal-rescue and welfare initiatives, and will publish a yearly impact report. We hold no inventory and make no carbon-neutral or zero-waste claims we cannot evidence.</p><h2 style="margin-top:40px">The Sustainable Development Goals we contribute to</h2><p class="mut">Select a goal to see how Furora contributes.</p><div class="paws">${SD.map((x,i)=>`<button class="paw" onclick="sdgOpen(${i})" aria-label="SDG ${x[0]}: ${x[1]}"><span class="pw"><svg viewBox="0 0 200 200" aria-hidden="true" fill="${x[2]}"><ellipse cx="38" cy="84" rx="19" ry="27" transform="rotate(-22 38 84)"/><ellipse cx="80" cy="42" rx="19" ry="29" transform="rotate(-8 80 42)"/><ellipse cx="120" cy="42" rx="19" ry="29" transform="rotate(8 120 42)"/><ellipse cx="162" cy="84" rx="19" ry="27" transform="rotate(22 162 84)"/><path d="M100 92c-26 0-62 34-62 62 0 22 18 32 38 28 10-2 16-5 24-5s14 3 24 5c20 4 38-6 38-28 0-28-36-62-62-62z"/></svg><span class="pi" data-img="img/sdg${x[0]}.jpg" style="background-color:${x[2]}"><span class="n" style="color:${x[3]}">${x[0]}</span></span></span><span class="cap"><b>SDG ${x[0]}</b><br>${x[1]}</span></button>`).join("")}</div><dialog id="sd"><div class="db"><span class="kicker" id="sk"></span><h2 id="st"></h2><p id="sp"></p><button class="btn line" onclick="$('#sd').close()">Close</button></div></dialog>`;
function sdgOpen(i){const x=SD[i];$("#sk").textContent="SDG "+x[0];$("#st").textContent=x[1];$("#sp").textContent=x[4];$("#sd").showModal()}
P.about=()=>`<section class="hero"><div><span class="kicker">About Furora</span><h1>Everything your pet needs, in one caring community.</h1><p class="mut">Furora makes responsible pet care easier to reach, supports local pet businesses, promotes adoption and extends the life of pet products through reuse.</p></div><div class="photo" data-img="img/hero/about.jpg" data-wp="Samoyed_dog" role="img" aria-label="A Samoyed dog"></div></section><div class="grid"><div class="card sky"><h3>Trust first</h3><p>Providers are verified, veterinary care stays with licensed professionals and credits are tracked in an auditable ledger.</p></div><div class="card sun"><h3>Adoption, not sale</h3><p>Shelters control applications and make the final decision. Our questionnaire only helps people prepare.</p></div><div class="card"><h3>Privacy by default</h3><p>We collect only what is needed and never sell personal data.</p></div><div class="card"><h3>Reuse and welfare</h3><p>Safe second-hand items get a second life, and 3% of net profit supports animal welfare.</p></div></div>`;
document.addEventListener("DOMContentLoaded",()=>{if(location.search.includes("imgdebug"))document.body.classList.add("imgdebug");try{cookieBanner()}catch(e){console.warn(e)}if(!guard())return;if(me()&&me().terms&&me().pet&&me().pet.name)runSchedules();nav();const a=$("#app");if(["index","terms","breed","setup","about","sustainability","refunds","cookies","contact"].includes(PAGE)||me())draw();else a.innerHTML=gate()});

const CK="furora:cookies2";
function cookieBanner(){try{if(localStorage.getItem(CK)&&!location.search.includes("cookies"))return}catch(e){}if(document.getElementById("ckd")||PAGE=="cookies")return;
 const d=document.createElement("dialog");d.id="ckd";d.className="ckd";d.setAttribute("aria-labelledby","ckt");d.addEventListener("cancel",e=>e.preventDefault());
 const save=v=>{try{localStorage.setItem(CK,JSON.stringify(v))}catch(e){}d.close();d.remove()};
 const main=()=>{d.innerHTML=`<div class="db"><h2 id="ckt">We use cookies</h2><p>Essential cookies keep you signed in and remember your choices. With your permission, we also use optional cookies to understand how Furora is used and to show offers that suit you. <a href="cookies.html">Cookie policy</a></p><div class="ckb"><button class="btn" id="cka" autofocus>Accept</button><button class="btn line" id="ckm">Manage</button><button class="btn line" id="ckr">Reject</button></div></div>`;
  $("#cka").onclick=()=>save({essential:1,analytics:1,marketing:1});$("#ckr").onclick=()=>save({essential:1,analytics:0,marketing:0});$("#ckm").onclick=manage};
 const manage=()=>{d.innerHTML=`<div class="db"><h2 id="ckt">Manage cookies</h2><div class="ckrow"><div><b>Essential</b><br><span class="mut">Keep you signed in and the site working. Always on.</span></div><input type="checkbox" checked disabled aria-label="Essential cookies"></div><div class="ckrow"><div><b>Analytics</b><br><span class="mut">Help us understand how Furora is used so we can improve it.</span></div><input type="checkbox" id="cka2" aria-label="Analytics cookies"></div><div class="ckrow"><div><b>Marketing</b><br><span class="mut">Show offers and promotions that suit you.</span></div><input type="checkbox" id="ckm2" aria-label="Marketing cookies"></div><div class="ckb" style="margin-top:20px"><button class="btn" id="cks">Save choices</button><button class="btn line" id="ckk">Back</button></div></div>`;
  $("#cks").onclick=()=>save({essential:1,analytics:$("#cka2").checked?1:0,marketing:$("#ckm2").checked?1:0});$("#ckk").onclick=main};
 document.body.appendChild(d);main();d.showModal()}
P.cookies=()=>`<div style="max-width:720px"><span class="kicker">Policy</span><h1>Cookies</h1><p>Cookies and similar browser storage are small pieces of data saved on your device.</p><h3>Essential</h3><p>These keep you signed in, remember your account data and store your cookie choice. Furora cannot work without them, so they are always on.</p><h3>Optional</h3><p>If you choose Accept all, we may use optional cookies to understand how Furora is used and improve it. If you choose Essential only, we will not.</p><h3>Your choice</h3><p>You can clear cookies and site data in your browser settings at any time. Doing so signs you out and shows this notice again.</p></div>`;

/* ===== Wishlist, cart, shipping, repeat orders, order tracking ===== */
let SNAP=[];
const PAW='<svg viewBox="0 0 200 200" fill="currentColor" aria-hidden="true"><ellipse cx="38" cy="84" rx="19" ry="27" transform="rotate(-22 38 84)"/><ellipse cx="80" cy="42" rx="19" ry="29" transform="rotate(-8 80 42)"/><ellipse cx="120" cy="42" rx="19" ry="29" transform="rotate(8 120 42)"/><ellipse cx="162" cy="84" rx="19" ry="27" transform="rotate(22 162 84)"/><path d="M100 92c-26 0-62 34-62 62 0 22 18 32 38 28 10-2 16-5 24-5s14 3 24 5c20 4 38-6 38-28 0-28-36-62-62-62z"/></svg>';
const CART='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 4h2l2.4 11h10.2l2-8H6.2"/><circle cx="9" cy="20" r="1.6"/><circle cx="17" cy="20" r="1.6"/></svg>';
const snapS=(sh,x)=>({k:sh.id+"|"+x[0],kind:"shop",n:x[0],p:x[1],sub:sh.n,wp:x[3],file:x[4],fit:true});
const snapW=s=>({k:"swap|"+s.t+"|"+s.by,kind:"swap",n:s.t,p:0,sub:s.type+" · "+s.by,wp:s.wp,file:s.file,img:s.img});
const inList=(l,k)=>(me()[l]||[]).some(x=>x.k==k);
const acts=sn=>{const i=SNAP.push(sn)-1;return `<div class="acts"><button class="ib" aria-label="Add ${esc(sn.n)} to wishlist" aria-pressed="${inList("wish",sn.k)}" onclick="wish(${i},this)">${PAW}</button><button class="ib" aria-label="Add ${esc(sn.n)} to cart" aria-pressed="${inList("cart",sn.k)}" onclick="addCart(${i},this)">${CART}</button></div>`};
function wish(i,b){const sn=SNAP[i];patch(u=>{u.wish=u.wish||[];const j=u.wish.findIndex(x=>x.k==sn.k);if(j>=0){u.wish.splice(j,1);b.setAttribute("aria-pressed","false");toast("Removed from wishlist.")}else{u.wish.push(sn);b.setAttribute("aria-pressed","true");toast("Added to wishlist.")}})}
function addCart(i,b){const sn=SNAP[i];patch(u=>{u.cart=u.cart||[];const x=u.cart.find(c=>c.k==sn.k);if(x){if(sn.kind=="shop")x.q++}else u.cart.push({...sn,q:1})});b&&b.setAttribute("aria-pressed","true");toast("Added to cart.");nav()}
const calc=c=>{const sub=Math.round(c.reduce((a,x)=>a+x.p*x.q,0)*100)/100,ship=c.length?(sub>=4?0:1):0;return{sub,ship,total:Math.round((sub+ship)*100)/100}};
const shipHtml=n=>n?`${n} credit`:`<s>1 credit</s><br><b>0 credits</b>`;
const fmt=t=>new Date(t).toLocaleString("en-GB",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"});
const STEPS=[["Order placed","We’ve received your order.",0],["Confirmed","The shop has confirmed your items.",5],["Preparing","Your items are being prepared.",60],["Packed","Your parcel is packed and waiting for the courier.",240],["Shipped","Handed to the courier.",1440],["Out for delivery","Your courier is on the way to you.",2880],["Delivered","Delivered to your address.",3600]];
function makeOrder(u,items,addr,at,sched,phone){const c=calc(items);if((u.credits||0)<c.total)return null;u.credits=Math.round((u.credits-c.total)*100)/100;const id="FUR-"+Math.floor(1e4+Math.random()*9e4);
 const o={id,at,addr,phone,items:items.map(x=>({n:x.n,p:x.p,q:x.q,kind:x.kind})),sub:c.sub,ship:c.ship,total:c.total,track:"FT"+Math.floor(1e8+Math.random()*9e8),carrier:"Furora Delivery (sample courier)",ev:STEPS.map(t=>({s:t[0],d:t[1],t:at+t[2]*6e4})),adv:0,sched:!!sched};
 (u.ord=u.ord||[]).unshift(o);(u.ledger=u.ledger||[]).unshift({t:`Order ${id}`+(sched?" (scheduled)":""),c:-c.total,at});return o}
const stat=o=>{const n=Date.now()+(o.adv||0);let i=0;o.ev.forEach((e,j)=>{if(e.t<=n)i=j});return i};
function ordHtml(o,open){if(o.failed)return `<div class="card sun" style="margin-bottom:14px"><b>${o.id}</b> · Scheduled order not placed (${esc(o.reason)}): ${esc(o.items[0].n)} × ${o.items[0].q}, ${fmt(o.at)}</div>`;const i=stat(o);
 return `<details class="topic" ${open?"open":""}><summary>Order ${o.id} <span class="tag ${i==6?"":"y"}">${o.ev[i].s}</span>${o.sched?` <span class="tag">Scheduled</span>`:""}</summary>
<ol class="trk">${o.ev.map((e,j)=>`<li class="${j<=i?"on":""}"><span></span>${e.s}</li>`).join("")}</ol>
<div class="row" style="margin:16px 0"><div><b>Tracking number</b><br>${o.track}</div><div><b>Carrier</b><br>${o.carrier}</div><div><b>Estimated delivery</b><br>${new Date(o.at+3*864e5).toLocaleDateString("en-GB",{weekday:"short",day:"numeric",month:"short"})}</div><div><b>Delivering to</b><br>${esc(o.addr)}</div><div><b>Phone</b><br>${esc(o.phone||"")}</div></div>
<h3>Tracking history</h3><ul class="tl">${o.ev.map((e,j)=>`<li class="${j<=i?"on":""}"><b>${e.s}</b> <span class="mut">${j<=i?fmt(e.t):"Expected "+fmt(e.t)}</span><br>${e.d}${e.s=="Shipped"&&j<=i?" Tracking number "+o.track+".":""}</li>`).join("")}</ul>
<h3>Items</h3>${o.items.map(x=>`<div class="sum"><span>${esc(x.n)} × ${x.q}</span><span>${x.p?cr(x.p*x.q)+" credits":"Free"}</span></div>`).join("")}<div class="sum"><span>Subtotal</span><span>${cr(o.sub)} credits</span></div><div class="sum"><span>Delivery</span><span class="r">${shipHtml(o.ship)}</span></div><div class="sum tot"><span>Total</span><span>${cr(o.total)} credits</span></div>
</details>`}
function ordersSec(){const u=me();return `<div class="note">Tracking is simulated in test mode until a courier or shop integration is connected.</div>${(u.ord||[]).map((o,i)=>ordHtml(o,i==0)).join("")||`<p class="mut">No orders yet. <a href="shop.html">Go pet shopping</a></p>`}`}
function wishSec(){const w=me().wish||[];return w.length?`<div class="grid">${w.map((x,i)=>`<div class="card"><div style="display:flex;gap:14px">${ph(x,"width:84px;height:84px;border-radius:16px;flex:none")}<div><h3 style="margin:0 0 4px;font-size:1.2rem">${esc(x.n)}</h3><span class="mut">${esc(x.sub)} · ${x.p?cr(x.p)+" credits":"Free"}</span></div></div><div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn sm" onclick="wishCart(${i})">Add to cart</button><button class="btn sm line" onclick="wishRm(${i})">Remove</button></div></div>`).join("")}</div>`:`<p class="mut">Select the paw on any product in the shops or Swap to save it here.</p>`}
const cartLink=u=>`<a class="l cartl" href="cart.html" aria-label="Cart">${CART}${(u.cart||[]).length?`<span class="cnt">${u.cart.reduce((a,x)=>a+x.q,0)}</span>`:""}</a>`;
function wishRm(i){patch(u=>u.wish.splice(i,1));draw()}
function wishCart(i){patch(u=>{const x=u.wish[i];u.cart=u.cart||[];const c=u.cart.find(y=>y.k==x.k);if(c){if(x.kind=="shop")c.q++}else u.cart.push({...x,q:1})});toast("Added to cart.");nav()}
P.cart=()=>{const u=me(),c=u.cart||[],t=calc(c);return `<span class="kicker">Cart</span><h1>My cart</h1>${c.length?`<div class="cartgrid"><div>${c.map((x,i)=>`<div class="line">${ph(x,"width:84px;height:84px;border-radius:16px;flex:none")}<div style="flex:1"><h3 style="margin:0">${esc(x.n)}</h3><span class="mut">${esc(x.sub)}</span><div class="qty"><button aria-label="Fewer" onclick="qty(${i},-1)">−</button><span>${x.q}</span><button aria-label="More" onclick="qty(${i},1)" ${x.kind=="swap"?"disabled":""}>+</button><button class="lnk" onclick="qty(${i},-99)">Remove</button></div></div><b>${x.p?cr(x.p*x.q)+" credits":"Free"}</b></div>`).join("")}</div>
<div class="card"><h3>Order summary</h3><div class="sum"><span>Subtotal</span><span>${cr(t.sub)} credits</span></div><div class="sum"><span>Delivery</span><span class="r">${shipHtml(t.ship)}</span></div>${t.ship?`<p class="mut"><small>Add ${cr(4-t.sub)} more credits of products for free delivery.</small></p>`:""}<div class="sum tot"><span>Total</span><span>${cr(t.total)} credits</span></div><p class="mut">Your balance: ${cr(u.credits||0)} credits</p><label for="ca2">Delivery address</label><input id="ca2" value="${esc(u.addr||"")}" autocomplete="street-address"><label for="cp">Phone number</label><input id="cp" type="tel" required value="${esc(u.phone||"")}" autocomplete="tel" placeholder="+389 70 000 000"><button class="btn" style="margin-top:18px;width:100%" onclick="checkout()">Place order</button></div></div>`:`<p class="mut">Your cart is empty.</p><a class="btn" href="shop.html">Go pet shopping</a>`}${schedHtml()}`};
function qty(i,d){patch(u=>{u.cart[i].q+=d;if(u.cart[i].q<1)u.cart.splice(i,1)});nav();draw()}
function checkout(){const u=me(),c=u.cart||[],a=$("#ca2").value.trim(),tel=$("#cp").value.trim();if(!c.length)return;if(!a){toast("Please add a delivery address.");return}if(!okTel(tel)){toast("Please add a valid phone number.");return}if((u.credits||0)<calc(c).total){toast("Not enough credits. Add a pack first.");return}let o;patch(u=>{o=makeOrder(u,c,a,Date.now(),false,tel);u.addr=a;u.phone=tel;u.cart=[]});location.href="pet.html#orders"}
const FOODS=()=>SHOPS[0].items;
function nextRun(s){const d=new Date();d.setHours(0,0,0,0);for(let i=0;i<62;i++){d.setDate(d.getDate()+1);if(s.days.includes(d.getDate()))return d.toLocaleDateString("en-GB",{day:"numeric",month:"short"})}return"–"}
function schedHtml(){const u=me(),L=u.sched||[];return `<h2 style="margin-top:64px">Repeat orders</h2><p class="mut">Choose a food and the days of the month you want it ordered. We place the order for you on those days and take the credits from your balance. If your balance is too low, that order is skipped and you’ll see a note in My orders. Days 29 to 31 aren’t offered so every month works.</p>${L.map((s,i)=>`<div class="card" style="margin-bottom:12px"><b>${esc(FOODS()[s.food][0])} × ${s.q}</b><br><span class="mut">Days of the month: ${s.days.join(", ")} · Next order: ${s.active?nextRun(s):"Paused"} · ${esc(s.addr)}</span><div style="display:flex;gap:8px;margin-top:12px"><button class="btn sm line" onclick="schedTog(${i})">${s.active?"Pause":"Resume"}</button><button class="btn sm line" onclick="schedDel(${i})">Delete</button></div></div>`).join("")}<form class="card" style="max-width:640px" onsubmit="schedAdd(event)"><h3>New repeat order</h3><label for="sf">Food</label><select id="sf">${FOODS().map((x,i)=>`<option value="${i}">${esc(x[0])} · ${x[1]} credits</option>`).join("")}</select><label for="sq">Quantity</label><input id="sq" type="number" min="1" max="5" value="1"><label>Days of the month</label><div class="days">${Array.from({length:28},(_,i)=>`<label class="dy"><input type="checkbox" value="${i+1}"><span>${i+1}</span></label>`).join("")}</div><label for="sa">Delivery address</label><input id="sa" required value="${esc(u.addr||"")}"><label for="sph">Phone number</label><input id="sph" type="tel" required value="${esc(u.phone||"")}" autocomplete="tel" placeholder="+389 70 000 000"><button class="btn" style="margin-top:20px">Start repeat order</button></form>`}
function schedAdd(e){e.preventDefault();const days=[...document.querySelectorAll(".days input:checked")].map(x=>+x.value);if(!days.length){toast("Select at least one day.");return}if(!okTel($("#sph").value)){toast("Please add a valid phone number.");return}const t=new Date();t.setHours(0,0,0,0);patch(u=>{u.addr=$("#sa").value;u.phone=$("#sph").value.trim();(u.sched=u.sched||[]).push({phone:$("#sph").value.trim(),food:+$("#sf").value,q:Math.max(1,+$("#sq").value||1),days,addr:$("#sa").value,active:true,last:t.getTime()})});toast("Repeat order started.");draw()}
function schedTog(i){patch(u=>{const s=u.sched[i];s.active=!s.active;const t=new Date();t.setHours(0,0,0,0);s.last=t.getTime()});draw()}
function schedDel(i){patch(u=>u.sched.splice(i,1));draw()}
function runSchedules(){const u0=me();if(!u0||!(u0.sched||[]).length)return;const today=new Date();today.setHours(0,0,0,0);let any=false;
 patch(u=>{u.sched.forEach(s=>{if(!s.active)return;const d=new Date(s.last);d.setDate(d.getDate()+1);let n=0;while(d<=today&&n++<62){if(s.days.includes(d.getDate())){const sn=snapS(SHOPS[0],FOODS()[s.food]),at=d.getTime()+9*36e5;if(!makeOrder(u,[{...sn,q:s.q}],s.addr,at,true,s.phone))(u.ord=u.ord||[]).unshift({id:"FUR-"+Math.floor(1e4+Math.random()*9e4),at,failed:true,reason:"not enough credits",items:[{n:sn.n,q:s.q}]});any=true}d.setDate(d.getDate()+1)}s.last=today.getTime()})});
 if(any)setTimeout(()=>toast("Your scheduled orders were placed."),600)}

const slug=t=>t.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
SHOPS.forEach(sh=>{sh.file=`img/shops/${sh.id}.jpg`;sh.items.forEach((x,i)=>x[4]=`img/products/${sh.id}-${i+1}.jpg`)});

const okTel=t=>/^[+()\d\s-]+$/.test(t)&&t.replace(/\D/g,"").length>=6;

/* Contact details: fill in what you want shown. Empty values are hidden. If email is set, the form also opens the visitor's email app. */
const CONTACT={email:"",phone:"",address:"Skopje, North Macedonia",hours:""};
P.contact=()=>{const u=me(),r=[["Address",CONTACT.address],["Email",CONTACT.email],["Phone",CONTACT.phone],["Opening hours",CONTACT.hours]].filter(x=>x[1]);
 return `<span class="kicker">Contact us</span><h1>We’d love to hear from you.</h1><p class="mut">Questions about an order, a booking, credits, adoption or the Swap? Send us a message.</p><div class="cartgrid"><form class="card" onsubmit="sendMsg(event)"><label for="cn">Your name</label><input id="cn" required value="${esc(u?u.name:"")}" autocomplete="name"><label for="ce">Email</label><input id="ce" type="email" required value="${esc(u?DB().session:"")}" autocomplete="email"><label for="ct">Topic</label><select id="ct" onchange="topicX()">${Object.keys(TOPICX).map(t=>`<option>${t}</option>`).join("")}</select><div id="cx"></div><label for="cm">Message</label><textarea id="cm" rows="6" required maxlength="2000"></textarea><button class="btn" style="margin-top:20px">Send message</button></form>
<div><div class="card sky" style="margin-bottom:20px"><h3>Contact details</h3>${r.map(x=>`<p style="margin:0 0 10px"><b>${x[0]}</b><br>${esc(x[1])}</p>`).join("")}</div><h3>Quick answers</h3><details class="topic"><summary style="font-size:1.15rem">Can I get a refund on credits?</summary><p>Purchased credits are non-refundable. Credits held for a booking return to your wallet if you cancel. See <a href="refunds.html">Cancellations and refunds</a>.</p></details><details class="topic"><summary style="font-size:1.15rem">Where do I track my order?</summary><p>Open My pet, then the My orders tab.</p></details><details class="topic"><summary style="font-size:1.15rem">Why is my swap item under inspection?</summary><p>Every item is checked briefly to keep swaps safe and the quality high.</p></details></div></div>`};
/* Extra questions shown for each contact topic: [label, type, options or placeholder] */
const TOPICX={
"Order help":[["Order number (optional)","text","FUR-12345"],["What is the problem?","select",["Where is my order?","Wrong or damaged item","Change delivery details","Other"]]],
"Booking":[["Service booked","text","e.g. Veterinary check-up"],["Provider","text",""],["Booking date (optional)","date",""]],
"Credits":[["What is this about?","select",["Adding credits","My balance looks wrong","Question about the refund policy","Other"]],["Approximate date of the transaction (optional)","date",""]],
"Adoption":[["Which dog are you asking about?","select",["Biskvit","Puma","Mufasa","Another dog","Not sure yet"]],["Have you applied on Lajka’s website?","select",["Not yet","Yes, I have applied","I’m not sure how"]]],
"Swap":[["Item name","text",""],["Your question is about","select",["My listing","Inspection of my item","Ordering an item","Something else"]]],
"Providers and shops":[["Business name","text",""],["Business type","select",["Veterinary clinic","Groomer","Pet hotel","Trainer","Dog walker","Pet shop"]]],
"Other":[["Subject","text",""]]};
function topicX(){const t=$("#ct").value;$("#cx").innerHTML=TOPICX[t].map((f,i)=>`<label for="cx${i}">${f[0]}</label>${f[1]=="select"?`<select id="cx${i}" class="cxf" data-l="${esc(f[0])}">${f[2].map(o=>`<option>${o}</option>`).join("")}</select>`:`<input id="cx${i}" class="cxf" data-l="${esc(f[0])}" type="${f[1]}" placeholder="${esc(f[2])}">`}`).join("")}
P.contact.after=topicX;
function sendMsg(e){e.preventDefault();const x=[...document.querySelectorAll(".cxf")].filter(i=>i.value).map(i=>[i.dataset.l,i.value]),m={n:$("#cn").value,e:$("#ce").value,t:$("#ct").value,x,m:$("#cm").value,at:Date.now()};const d=DB();(d.msgs=d.msgs||[]).push(m);put(d);
 const body=m.m+"\n\n"+x.map(y=>y[0]+": "+y[1]).join("\n")+"\n\n"+m.n+" ("+m.e+")";
 if(CONTACT.email)location.href=`mailto:${CONTACT.email}?subject=${encodeURIComponent("Furora: "+m.t)}&body=${encodeURIComponent(body)}`;
 e.target.reset();topicX();toast("Thank you. Your message has been saved.")}

/* Logo: save your logo as img/furora-logo.png (or .jpg, .jpeg, .webp). It appears before the word Furora, top left. */
function loadLogo(){const el=document.querySelector(".lgimg");if(el)tryImg(cands("img/furora-logo.png"),u=>{el.src=encodeURI(u);el.hidden=false},()=>{})}
